// PRUEBA 1: Verificar código 201
pm.test("Usuario creado con estado 201", function () {
    pm.response.to.have.status(201);
});

// PRUEBA 2: Verificar estructura de respuesta
pm.test("La respuesta contiene los datos del usuario", function () {
    const usuario = pm.response.json();

    pm.expect(usuario).to.have.property("id");
    pm.expect(usuario).to.have.property("name");
    pm.expect(usuario).to.have.property("email");
});

// PRUEBA 3: Verificar nombre
pm.test("El nombre del usuario es correcto", function () {
    const usuario = pm.response.json();

    pm.expect(usuario.name).to.eql("Carlos Pruebas");
});

// PRUEBA 4: Verificar correo
pm.test("El correo electrónico es correcto", function () {
    const usuario = pm.response.json();

pm.expect(usuario.email).to.eql(
    "carlos.pruebas3@demo.com"
);
});

// PRUEBA 5: Verificar que no se exponga la contraseña
pm.test("La respuesta no contiene contraseña", function () {
    const usuario = pm.response.json();

    pm.expect(usuario).to.not.have.property("password");
});

// PRUEBA 1: Verificar código 409
pm.test("El sistema rechaza el registro duplicado", function () {
    pm.response.to.have.status(409);
});

// PRUEBA 2: Verificar mensaje de error
pm.test("El mensaje indica que el correo ya existe", function () {
    const respuesta = pm.response.json();

    pm.expect(respuesta.detail).to.eql(
        "El correo ya está registrado"
    );
});

// PRUEBA 3: Verificar que no se creó otro usuario
pm.test("La respuesta no contiene un nuevo ID", function () {
    const respuesta = pm.response.json();

    pm.expect(respuesta).to.not.have.property("id");
});

// PRUEBA 1: Verificar código HTTP 200
pm.test("Inicio de sesión responde con estado 200", function () {
    pm.response.to.have.status(200);
});

// PRUEBA 2: Verificar mensaje de éxito
pm.test("El mensaje de inicio de sesión es correcto", function () {
    const respuesta = pm.response.json();

    pm.expect(respuesta.message).to.eql(
        "Inicio de sesión exitoso"
    );
});

// PRUEBA 3: Verificar información del usuario
pm.test("La respuesta contiene los datos del usuario", function () {
    const respuesta = pm.response.json();

    pm.expect(respuesta.user).to.have.property("id");
    pm.expect(respuesta.user).to.have.property("name");
    pm.expect(respuesta.user).to.have.property("email");
});

// PRUEBA 4: Verificar correo del usuario
pm.test("El correo corresponde al administrador", function () {
    const respuesta = pm.response.json();

    pm.expect(respuesta.user.email).to.eql(
        "admin@demo.com"
    );
});

// PRUEBA 5: Verificar que no se exponga la contraseña
pm.test("La respuesta no contiene contraseña", function () {
    const respuesta = pm.response.json();

    pm.expect(respuesta.user).to.not.have.property("password");
});

// PRUEBA 1: Verificar código 401
pm.test("El sistema rechaza las credenciales incorrectas", function () {
    pm.response.to.have.status(401);
});

// PRUEBA 2: Verificar mensaje de error
pm.test("El mensaje de error es correcto", function () {
    const respuesta = pm.response.json();

    pm.expect(respuesta.detail).to.eql(
        "Correo o contraseña incorrectos"
    );
});

// PRUEBA 3: Verificar que no se entregue información del usuario
pm.test("La respuesta no contiene datos del usuario", function () {
    const respuesta = pm.response.json();

    pm.expect(respuesta).to.not.have.property("user");
});
